using System.Reflection;
using RecompOne.Runtime;
using RecompOne.Runtime.Context;
using RecompOne.Runtime.Dispatch;
using RecompOne.Runtime.Memory;
using RecompOne.Runtime.Sdk;

// Test inputs are generated by test_guest_engine_audio.py --write-fixture.
// Native SPU allocation is stubbed; the project loader, table attachment,
// address/pitch reads, SPU ADPCM decoding and PCM mixer are the production ones.
string dir = args.Single();
Console.WriteLine(V82VehicleRegistry.ValidatePackage(dir));
Runtime.SetMode(RunMode.Devkit);
var m = new PSMemory();
var c = new CpuContext { SP = 0x80070000 };
var spu = Runtime.Spu!;
const uint car = 0x80042000, body = 0x80044000, sampleBase = 0x4000;
int checks = 0;
void Check(bool ok, string why) { if (!ok) throw new Exception(why); checks++; }
Dispatcher.RegisterHostFunction(0x80052F9C, (ctx, _) => ctx.V0 = sampleBase);
var payload = File.ReadAllBytes(Path.Combine(dir, "SYNTHETIC.SND"));
typeof(V82VehicleRegistry).GetMethod("AttachSoundBank", BindingFlags.NonPublic | BindingFlags.Static)!
    .Invoke(null, new object[] { c, m, body, payload });
uint handle = m.ReadU32(body + 12);
Check(m.ReadU16(handle) == 3, "two old effects and one original engine uploaded");
m.WriteU8(car + 0xDC, 64);
uint sample = V82VehicleRegistry.GroundEngineSample(m, car, 0);
Check(sample == 2, "first guest selects its appended engine rather than weapon zero");
m.WriteU8(car + 0xDC, 65);
Check(V82VehicleRegistry.GroundEngineSample(m, car, 0) == 1, "second guest uses its own index");
m.WriteU8(car + 0xDC, 66);
Check(V82VehicleRegistry.GroundEngineSample(m, car, 0) == 0, "legacy/mod package default unchanged");
m.WriteU8(car + 0xDC, 6);
Check(V82VehicleRegistry.GroundEngineSample(m, car, 0) == 0, "stock sample unchanged");
m.WriteU8(car + 0xDC, 64);
foreach (uint nonGround in new uint[]{21,22,23})
    Check(V82VehicleRegistry.GroundEngineSample(m, car, nonGround) == nonGround, "native transform sample unchanged");

// Materialize the same sample address/pitch the native sound player reads.
// Verify nonzero PCM *after* the one-shot duration: an initial click is not an engine.
uint record = handle + 4 + 4 * sample;
Check(m.ReadU16(record) << 3 == sampleBase + 64, "native offset targets the third sound");
Check(m.ReadU16(record + 2) == 1032, "authored engine pitch preserved");
const uint ch = 0x1F801C00, master = 0x1F801D80;
m.WriteU16(master, 0x3FFF); m.WriteU16(master+2, 0x3FFF);
m.WriteU16(ch, 0x3FFF); m.WriteU16(ch+2, 0x3FFF);
m.WriteU16(ch+8, 0x000F); m.WriteU16(ch+10, 0);
bool TailHasPcm(uint index)
{
    uint e = handle + 4 + 4 * index;
    m.WriteU16(ch+4, m.ReadU16(e+2)); m.WriteU16(ch+6, m.ReadU16(e));
    m.WriteU16(master+8, 1);
    var mixed = new short[8192]; spu.Mix(mixed, mixed.Length/2);
    return mixed.AsSpan(7000).ToArray().Any(v=>v!=0);
}
Check(!TailHasPcm(0), "old body effect ends instead of faking sustained engine audio");
Check(TailHasPcm(sample), "mapped engine produces sustained PCM through the real SPU");
Console.WriteLine($"{checks} ground-engine checks passed");
